-- Fakt kartochkalarining ruscha matni — 16-partiya:
-- Bumin xoqon, Istami xoqon, Mahmud az-Zamaxshariy, Burhoniddin Marg'inoniy.

-- ===== Bumin xoqon =====
UPDATE fact_cards SET topic_ru = 'Кто я?', question_ru = 'Какому государству положил начало Бумын-каган?', fact_ru = 'Я Бумын-каган — основатель великой державы, вошедшей в историю под именем Тюркского каганата.' WHERE id = 521;
UPDATE fact_cards SET topic_ru = 'Объединение племён', question_ru = 'Тюркские племена каких земель объединил Бумын-каган?', fact_ru = 'В середине VI века я объединил тюркские племена, жившие на Алтае и в Южной Сибири, и создал новое государство.' WHERE id = 522;
UPDATE fact_cards SET topic_ru = '552 год', question_ru = 'В каком году Бумын был провозглашён каганом?', fact_ru = 'В 552 году я был провозглашён каганом.' WHERE id = 523;
UPDATE fact_cards SET topic_ru = 'Титул кагана', question_ru = 'Что означает слово «каган»?', fact_ru = 'Слово «каган» означает великий правитель, государь.' WHERE id = 524;
UPDATE fact_cards SET topic_ru = 'Средоточие державы', question_ru = 'Где было средоточие Тюркского каганата?', fact_ru = 'Средоточием нашего каганата был определён Алтайский край.' WHERE id = 525;
UPDATE fact_cards SET topic_ru = 'Расширение державы', question_ru = 'Какие земли заняли тюрки в 555 году?', fact_ru = 'Основанное мной государство быстро расширялось: уже в 555 году тюрки заняли обширные земли, простиравшиеся до берегов Сырдарьи и Аральского моря.' WHERE id = 526;
UPDATE fact_cards SET topic_ru = 'Истеми и западные походы', question_ru = 'Кто возглавлял походы тюрок на запад?', fact_ru = 'Походы тюрок на запад возглавлял Истеми; ему был дан титул «ябгу-каган».' WHERE id = 527;
UPDATE fact_cards SET topic_ru = 'Судьба каганата', question_ru = 'На сколько государств разделился Тюркский каганат?', fact_ru = 'Позже, в конце 80-х годов VI века, каганат разделился на Восточно-тюркский и Западно-тюркский каганаты.' WHERE id = 528;
UPDATE fact_cards SET topic_ru = 'Моё имя в китайских источниках', question_ru = 'В каком виде записано имя Бумын-кагана в древних китайских источниках?', fact_ru = 'В древних китайских летописях моё имя записано в виде «Тумын». Многое обо мне учёные узнали именно из этих источников.' WHERE id = 1550;
UPDATE fact_cards SET topic_ru = 'Род Ашина', question_ru = 'Из какого рода происходил Бумын-каган?', fact_ru = 'Я происхожу из рода Ашина, возглавлявшего тюркские племена. Правители Тюркского каганата были из этого рода.' WHERE id = 1551;
UPDATE fact_cards SET topic_ru = 'Кузнечное ремесло', question_ru = 'Каким ремеслом славились тюркские племена под началом Бумын-кагана?', fact_ru = 'Ещё до создания каганата наши племена добывали железо в Алтайских горах и славились кузнечным делом. Мы были искусными мастерами в изготовлении оружия и орудий из железа.' WHERE id = 1552;
UPDATE fact_cards SET topic_ru = 'Моя победа над племенами теле', question_ru = 'Какие племена подчинил себе Бумын-каган в 546 году?', fact_ru = 'В 546 году я подчинил себе племена теле и объединил их под своей рукой. Эта победа заметно умножила мою силу.' WHERE id = 1553;
UPDATE fact_cards SET topic_ru = 'Союз с державой Вэй', question_ru = 'С каким государством в Китае Бумын-каган заключил союз?', fact_ru = 'На пути к усилению я установил дружественные связи с государством Западная Вэй в Китае и женился на их царевне. Этот союз помог укрепить моё государство.' WHERE id = 1554;
UPDATE fact_cards SET topic_ru = 'Моё имя в орхонских надписях', question_ru = 'В каких древних каменных надписях Бумын-каган упомянут как основатель государства?', fact_ru = 'В знаменитых орхонских надписях, позже высеченных на камне, я с почтением упомянут как основатель каганата.' WHERE id = 1555;
UPDATE fact_cards SET topic_ru = 'Мои наследники', question_ru = 'При каком сыне Бумын-кагана Тюркский каганат особенно усилился?', fact_ru = 'После меня на престол сели мои сыновья. Особенно усилилась наша держава при моём сыне Мукан-кагане.' WHERE id = 1556;

-- ===== Istami xoqon =====
UPDATE fact_cards SET topic_ru = 'Кто я?', question_ru = 'Что возглавлял Истеми-каган в Тюркском каганате?', fact_ru = 'Я Истеми-каган — в Тюркском каганате я возглавлял походы тюрок на запад.' WHERE id = 529;
UPDATE fact_cards SET topic_ru = 'Мой титул', question_ru = 'Какой титул был дан Истеми-кагану?', fact_ru = 'Мне был дан титул «ябгу-каган»; до звания ябгу возвышались только кровные родичи каганского рода.' WHERE id = 530;
UPDATE fact_cards SET topic_ru = 'Восточные земли', question_ru = 'Какие земли были подчинены в итоге походов Истеми-кагана?', fact_ru = 'В итоге наших походов были подчинены тюркские племена, жившие в Семиречье и на землях, примыкающих к Восточному Туркестану.' WHERE id = 531;
UPDATE fact_cards SET topic_ru = 'Обширные земли', question_ru = 'Какие земли заняли тюрки в 555 году?', fact_ru = 'Уже в 555 году тюрки заняли обширные земли, простиравшиеся до берегов Сырдарьи и Аральского моря.' WHERE id = 532;
UPDATE fact_cards SET topic_ru = 'Союз с Ираном', question_ru = 'С каким государством Истеми-каган заключил военный союз?', fact_ru = 'По почину иранского шаха Хосрова I Ануширвана мы заключили военный союз; этот союз ещё больше окреп оттого, что иранский шах стал моим зятем.' WHERE id = 533;
UPDATE fact_cards SET topic_ru = 'Поход против эфталитов', question_ru = 'Какие города заняли тюркские войска в 563 году?', fact_ru = 'В 563 году наши войска вступили в земли государства эфталитов и заняли города Чач, Самарканд, Кеш и Нахшеб; в жестокой битве, длившейся восемь дней, войско эфталитов было разбито.' WHERE id = 534;
UPDATE fact_cards SET topic_ru = 'Конец державы эфталитов', question_ru = 'Какие земли отошли к Тюркскому каганату после падения державы эфталитов?', fact_ru = 'После того как в 563–567 годах держава эфталитов пала, земли по правым берегам Амударьи вплоть до Каспийского моря отошли во владение Тюркского каганата.' WHERE id = 535;
UPDATE fact_cards SET topic_ru = 'Торговля на Шёлковом пути', question_ru = 'С кем торговали тюрки на Великом шёлковом пути?', fact_ru = 'После этого тюрки деятельно участвовали в караванной торговле Великого шёлкового пути и стали через Иран торговать напрямую с Византией.' WHERE id = 536;
UPDATE fact_cards SET topic_ru = 'Мой брат Бумын-каган', question_ru = 'Кем приходился Истеми-каган Бумын-кагану, основателю Тюркского каганата?', fact_ru = 'Я младший брат Бумын-кагана, основавшего Тюркский каганат. Мой брат положил начало каганату в 552 году, а я был его ближайшим сподвижником.' WHERE id = 1664;
UPDATE fact_cards SET topic_ru = 'Посольство в Византию', question_ru = 'Кто возглавлял послов, отправленных Истеми-каганом в Византию?', fact_ru = 'В 568 году я отправил в столицу Византии Константинополь послов во главе с согдийским купцом Маниахом. Мои послы вели у императора переговоры о торговле шёлком.' WHERE id = 1665;
UPDATE fact_cards SET topic_ru = 'Византийский посол у меня в гостях', question_ru = 'Как звали византийского посла, прибывшего к Истеми-кагану?', fact_ru = 'В ответ византийский император направил ко мне послов во главе с Земархом. Я принял их в своей ставке на Золотой горе.' WHERE id = 1666;
UPDATE fact_cards SET topic_ru = 'Амударья — граница', question_ru = 'Какая река была границей между Тюркским каганатом и Ираном во времена Истеми-кагана?', fact_ru = 'После поражения державы эфталитов Амударья стала границей между Тюркским каганатом и Ираном.' WHERE id = 1667;
UPDATE fact_cards SET topic_ru = 'Моё имя на каменных стелах', question_ru = 'На какой древнетюркской каменной стеле упомянуто имя Истеми-кагана?', fact_ru = 'Моё имя сохранилось на древнетюркских каменных стелах: в надписи «Кюль-тегин» на берегу реки Орхон моё имя упомянуто вместе с именем Бумын-кагана.' WHERE id = 1668;
UPDATE fact_cards SET topic_ru = 'Мой сын Тарду', question_ru = 'Кто правил западной частью каганата после Истеми-кагана?', fact_ru = 'После меня западной частью каганата правил мой сын Тарду.' WHERE id = 1669;
UPDATE fact_cards SET topic_ru = 'Время моей жизни', question_ru = 'В каком веке жил Истеми-каган?', fact_ru = 'Я жил в VI веке — в эту пору Тюркский каганат стал одной из могущественнейших держав Азии.' WHERE id = 1670;

-- ===== Mahmud az-Zamaxshariy =====
UPDATE fact_cards SET topic_ru = 'Моё рождение', question_ru = 'Когда и где родился Махмуд аз-Замахшари?', fact_ru = 'Я родился 18 марта 1075 года в хорезмском селении Замахшар. Моё полное имя — Абулкасим Махмуд ибн Умар ибн Ахмад. Первые знания я получил от отца, человека набожного и богобоязненного.' WHERE id = 1877;
UPDATE fact_cards SET topic_ru = 'Испытание моего детства', question_ru = 'С каким испытанием столкнулся Замахшари в юности?', fact_ru = 'В юности я упал с коня и повредил ногу. Отец хотел обучить меня ремеслу портного, но я выбрал путь науки.' WHERE id = 1878;
UPDATE fact_cards SET topic_ru = 'Мои наставники', question_ru = 'У каких наставников учился Замахшари и какими науками овладел?', fact_ru = 'Я учился у таких наставников, как Абу Мудар Исфахани, Абумансур Наср Хариси, Абусад Шаккани и Абулхаттаб ибн Абулбатр, а также обучался в Бухаре. Особенно основательно я овладел арабским языком и словесностью, религиозными науками и искусством каллиграфии.' WHERE id = 1879;
UPDATE fact_cards SET topic_ru = 'Мои странствия', question_ru = 'В какие годы и в какие города странствовал Замахшари?', fact_ru = 'За свою жизнь я дважды — в 1100–1122 и 1127–1139 годах — отправлялся в долгие странствия по мусульманскому Востоку. Я побывал в Мерве, Нишапуре, Исфахане, Дамаске и Мекке, а в 1109 году направился в Багдад.' WHERE id = 1880;
UPDATE fact_cards SET topic_ru = 'Моё прозвище Джаруллах', question_ru = 'Почему Замахшари получил прозвище «Джаруллах»?', fact_ru = 'За то, что я долго жил в священном городе Мекке и писал там свои труды, мне было дано почётное прозвище «Джаруллах», то есть «сосед Аллаха». Называли меня также «Устаз уд-дунё» и «Фахру Хорезм».' WHERE id = 1881;
UPDATE fact_cards SET topic_ru = 'Мой труд «Аль-Кашшаф»', question_ru = 'Как называется знаменитый труд Замахшари, посвящённый толкованию Корана?', fact_ru = 'Свой самый знаменитый труд — толкование «Аль-Кашшаф» — я написал в 1132–1134 годах в Мекке. Этого моего труда, посвящённого толкованию Священного Корана, сохранилось около 100 рукописей.' WHERE id = 1882;
UPDATE fact_cards SET topic_ru = '«Мукаддимат ул-адаб»', question_ru = 'Кому посвящён труд «Мукаддимат ул-адаб» и чем он ценен?', fact_ru = 'В 1137 году я написал труд «Мукаддимат ул-адаб» («Введение в науку словесности») и посвятил его хорезмшаху Атсызу. В нём под арабскими словами я дал персидские и тюркские переводы; труд состоит из 5 больших частей.' WHERE id = 1883;
UPDATE fact_cards SET topic_ru = 'Мой труд «Аль-Муфассаль»', question_ru = 'Какой труд Замахшари посвящён грамматике арабского языка?', fact_ru = 'В 1121 году я написал труд «Аль-Муфассаль», посвящённый грамматике арабского языка. Эта моя книга снискала большую славу и на Востоке, и на Западе.' WHERE id = 1884;
UPDATE fact_cards SET topic_ru = 'Мои труды и ученики', question_ru = 'Сколько трудов написал Замахшари и сколько из них сохранилось?', fact_ru = 'Я написал около 50 трудов по языкознанию, словесности, географии, толкованию Корана и науке хадисов, из них 25 дошли до нас. Я воспитал более 200 учеников.' WHERE id = 1885;
UPDATE fact_cards SET topic_ru = 'Конец моей жизни', question_ru = 'Когда и где умер Замахшари?', fact_ru = 'В 1139 году я вернулся на родину, в Хорезм, и прожил там до конца своих дней. Я скончался в 1144 году на месте нынешнего Куня-Ургенча и там же погребён.' WHERE id = 1886;

-- ===== Burhoniddin Marg'inoniy =====
UPDATE fact_cards SET topic_ru = 'Моё рождение', question_ru = 'Когда и где родился Бурханиддин Маргинани?', fact_ru = 'Я родился в 1123 году в селении Риштан под Маргиланом, в Ферганской долине. Первое образование я получил на родине, в Риштане, потому что и Риштан в ту пору был одним из очагов науки и просвещения.' WHERE id = 1887;
UPDATE fact_cards SET topic_ru = 'Моё имя и звание', question_ru = 'Что означает звание «Бурханиддин» и каково настоящее имя учёного?', fact_ru = 'Моё настоящее имя — Али, а за глубокое знание науки фикха мне было дано звание «Бурханиддин» — «довод веры, свидетельство веры». Полное моё имя — Абуль Хасан Али ибн Абу Бакр ибн Абдульджамиль аль-Фаргани ар-Риштани аль-Маргинани.' WHERE id = 1888;
UPDATE fact_cards SET topic_ru = 'Моя родина Маргилан', question_ru = 'Каким именем был отмечен город Маргилан за обилие учёных?', fact_ru = 'На моей родине, в Маргилане, в одну лишь пору жило более семидесяти учёных, удостоенных звания «Мавляна». Потому Маргилан и заслужил признание как «Сундукуль орифийн», то есть обитель познавших.' WHERE id = 1889;
UPDATE fact_cards SET topic_ru = 'Начало в чиллахане', question_ru = 'Где Бурханиддин Маргинани начал писать труд «Хидоя»?', fact_ru = 'Первые части моего труда «Хидоя» я начал писать, ещё живя в Маргилане, а затем отправился в Самарканд и продолжил свои занятия наукой. Я скончался в 1197 году; позже народ назвал место, где я творил, «чиллаханой Сахиби Хидоя» — эта святыня находится подле святыни Пур Сиддик в Маргилане.' WHERE id = 1890;
UPDATE fact_cards SET topic_ru = 'Моя учёба в Самарканде', question_ru = 'В каком городе Маргинани продолжил своё обучение?', fact_ru = 'Хотя я родился и вырос в ферганском краю, обучение я продолжил в Самарканде — одном из научных средоточий того времени. Там я встречался со многими учёными и участвовал в научных спорах.' WHERE id = 1891;
UPDATE fact_cards SET topic_ru = 'Мой труд «Хидоя»', question_ru = 'Когда и где был окончен труд «Хидоя»?', fact_ru = 'Свой труд «Хидоя», прославившийся во всём исламском мире, я окончил в 573 году хиджры, то есть в 1178 году, в Самарканде. Эта книга стала во всём исламском мире основным пособием по вопросам фикха ханафитского мазхаба и главным учебником, преподаваемым в медресе.' WHERE id = 1892;
UPDATE fact_cards SET topic_ru = 'Мои другие труды', question_ru = 'Какие труды Маргинани легли в основу «Хидои»?', fact_ru = 'Основой моего главного труда «аль-Хидоя» стали книги «Бидоят аль-мубтади» («Первое обучение для начинающих») и «Кифоят аль-мунтахи» («Полное обучение для завершающих»). Кроме них я написал и такие труды, как «Нашр аль-мазхаб», «Манасик аль-хадж», «Китаб аль-фараид».' WHERE id = 1893;
UPDATE fact_cards SET topic_ru = 'Мои наставники', question_ru = 'Скольких своих наставников перечислил Маргинани в труде «Китаб уль-машоих»?', fact_ru = 'В труде «Китаб уль-машоих» я перечислил более 40 шейхов и учёных, у которых сам учился. Среди них такие мои наставники, как Наджмуддин Умар ибн Мухаммад ан-Насафи и Джафар аль-Хиндувани.' WHERE id = 1894;
UPDATE fact_cards SET topic_ru = 'Моя поездка в Ирак', question_ru = 'Какой знаменитый труд по фикху увидел Маргинани в поездке в Ирак?', fact_ru = 'Когда я странствовал в Ирак, я увидел «Аль-Мухтасар аль-Кудури» — превосходный труд по фикху; в ту пору все, от мала до велика, пользовались «Джами ус-сагир». Тогда я и собрал воедино труды по фикху, взяв из них самые необходимые вопросы.' WHERE id = 1895;
UPDATE fact_cards SET topic_ru = 'Конец моей жизни', question_ru = 'Когда умер Бурханиддин Маргинани и где он погребён?', fact_ru = 'В 1197 году я во второй раз собрался в хадж, но, не успев покинуть Самарканд, скончался от тяжкой болезни. Я умер 14-го числа месяца зульхиджа 593 года хиджры — 29 октября 1197 года — и погребён на самаркандском кладбище Чакардиза.' WHERE id = 1896;
